{
 "ok": true,
 "tool": "capabilities",
 "revision": 16,
 "schemaVersion": 2,
 "tools": [
  {
   "name": "plan.execute",
   "mcp": "execute_plan",
   "cli": "execute",
   "kind": "mutation",
   "summary": "Execute a mai.agent-plan/v1: constraints (preserve parts against a snapshot/baseline) + commands (variant.apply, identity.preserve, animation.adjust) compiled on a draft, validated (structural/identity/perceptual gates), previewed, and committed as ONE transaction with one undoToken. mode \"dry-run\" changes nothing. requestId is an idempotency key.",
   "when": "Whenever one human request maps to several changes (\"la primera con los ojos de la tercera, conserva la boca y baja 30% el humo\").",
   "input": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "plan"
    ],
    "properties": {
     "plan": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "$id": "urn:mai:agent-plan:v1",
      "title": "MAI Agent Plan v1",
      "description": "Runtime contract of plan.execute (validated by packages/agent/plan.ts with Ajv). Semantic validation and snapshot preconditions apply in addition to this schema.",
      "type": "object",
      "additionalProperties": false,
      "required": [
       "protocol",
       "requestId",
       "sessionId",
       "documentId",
       "expectedRevision",
       "mode",
       "label",
       "commands",
       "validation",
       "provenance"
      ],
      "properties": {
       "protocol": {
        "const": "mai.agent-plan/v1"
       },
       "requestId": {
        "$ref": "#/$defs/id"
       },
       "sessionId": {
        "$ref": "#/$defs/id"
       },
       "documentId": {
        "$ref": "#/$defs/id"
       },
       "expectedRevision": {
        "type": "integer",
        "minimum": 0
       },
       "mode": {
        "enum": [
         "dry-run",
         "commit"
        ]
       },
       "label": {
        "type": "string",
        "minLength": 1,
        "maxLength": 120
       },
       "constraints": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "preserve"
        ],
        "properties": {
         "preserve": {
          "type": "array",
          "minItems": 1,
          "maxItems": 32,
          "items": {
           "$ref": "#/$defs/preserve"
          }
         }
        }
       },
       "commands": {
        "type": "array",
        "minItems": 1,
        "maxItems": 64,
        "items": {
         "oneOf": [
          {
           "$ref": "#/$defs/variantApply"
          },
          {
           "$ref": "#/$defs/identityPreserve"
          },
          {
           "$ref": "#/$defs/animationAdjust"
          }
         ]
        }
       },
       "validation": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "times",
         "required",
         "preview"
        ],
        "properties": {
         "times": {
          "type": "array",
          "minItems": 1,
          "maxItems": 8,
          "uniqueItems": true,
          "items": {
           "type": "number",
           "minimum": 0,
           "maximum": 300
          }
         },
         "required": {
          "type": "array",
          "minItems": 1,
          "maxItems": 3,
          "uniqueItems": true,
          "contains": {
           "const": "structural"
          },
          "items": {
           "enum": [
            "structural",
            "identity",
            "perceptual"
           ]
          }
         },
         "preview": {
          "type": "boolean"
         }
        }
       },
       "provenance": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "kind",
         "text"
        ],
        "properties": {
         "kind": {
          "enum": [
           "user-direction",
           "editor-choice",
           "agent-proposal"
          ]
         },
         "text": {
          "type": "string",
          "minLength": 1,
          "maxLength": 4000
         },
         "referenceId": {
          "$ref": "#/$defs/id"
         }
        },
        "description": "Audit context only. Claimed provenance is not proof of human authorization. An agent-proposal may prepare but may not accept a pending choice without user direction."
       }
      },
      "$defs": {
       "id": {
        "type": "string",
        "minLength": 1,
        "maxLength": 128,
        "pattern": "^[A-Za-z0-9][A-Za-z0-9_.:-]*$"
       },
       "part": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "partId"
        ],
        "properties": {
         "partId": {
          "$ref": "#/$defs/id"
         },
         "within": {
          "$ref": "#/$defs/id"
         }
        },
        "description": "Stable semantic ID in the plan document. within is an optional owner character/part ID, checked before mutation; no fuzzy text matching."
       },
       "reference": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "kind",
         "id"
        ],
        "properties": {
         "kind": {
          "enum": [
           "snapshot",
           "baseline"
          ]
         },
         "id": {
          "$ref": "#/$defs/id"
         }
        }
       },
       "preserve": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "part",
         "reference",
         "channels",
         "allowRigidMotion"
        ],
        "properties": {
         "part": {
          "$ref": "#/$defs/part"
         },
         "reference": {
          "$ref": "#/$defs/reference"
         },
         "channels": {
          "type": "array",
          "minItems": 1,
          "maxItems": 3,
          "uniqueItems": true,
          "items": {
           "enum": [
            "geometry",
            "paint",
            "expression"
           ]
          }
         },
         "allowRigidMotion": {
          "type": "boolean"
         }
        },
        "description": "Captured before all commands. Preserves local evaluated channels at validation.times; rigid alignment must be explicit and bounded."
       },
       "variantApply": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "id",
         "type",
         "target",
         "board",
         "base"
        ],
        "properties": {
         "id": {
          "$ref": "#/$defs/id"
         },
         "type": {
          "const": "variant.apply"
         },
         "target": {
          "$ref": "#/$defs/part"
         },
         "board": {
          "type": "object",
          "additionalProperties": false,
          "required": [
           "id",
           "version"
          ],
          "properties": {
           "id": {
            "$ref": "#/$defs/id"
           },
           "version": {
            "type": "integer",
            "minimum": 1
           }
          }
         },
         "base": {
          "$ref": "#/$defs/id"
         },
         "take": {
          "type": "object",
          "additionalProperties": false,
          "minProperties": 1,
          "properties": {
           "mouth": {
            "$ref": "#/$defs/id"
           },
           "eyes": {
            "$ref": "#/$defs/id"
           },
           "brows": {
            "$ref": "#/$defs/id"
           },
           "ears": {
            "$ref": "#/$defs/id"
           }
          }
         },
         "rechoose": {
          "type": "boolean",
          "description": "The board was already chosen and the human changed their mind: the new acceptance supersedes the latest one in the same transaction (parameters of the previous option that the new one does not set return to 0; preserved slots are kept). Undo returns to the previous acceptance."
         }
        }
       },
       "identityPreserve": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "id",
         "type",
         "target",
         "reference",
         "policy"
        ],
        "properties": {
         "id": {
          "$ref": "#/$defs/id"
         },
         "type": {
          "const": "identity.preserve"
         },
         "target": {
          "$ref": "#/$defs/part"
         },
         "reference": {
          "$ref": "#/$defs/reference"
         },
         "policy": {
          "enum": [
           "locked",
           "protected",
           "deformable",
           "style-preserved",
           "topology-preserved",
           "color-preserved",
           "silhouette-preserved"
          ]
         }
        },
        "description": "Adds persistent constraints; cannot weaken existing protection. Requires the identity validation gate. Not an implicit reset to neutral geometry."
       },
       "animationAdjust": {
        "type": "object",
        "additionalProperties": false,
        "required": [
         "id",
         "type",
         "target",
         "sourceId",
         "property",
         "scale",
         "onOverflow"
        ],
        "properties": {
         "id": {
          "$ref": "#/$defs/id"
         },
         "type": {
          "const": "animation.adjust"
         },
         "target": {
          "$ref": "#/$defs/part"
         },
         "sourceId": {
          "$ref": "#/$defs/id"
         },
         "property": {
          "const": "speed"
         },
         "scale": {
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 20
         },
         "onOverflow": {
          "const": "reject"
         }
        },
        "description": "First slice: scale one resolved animation source. A factor of 0.7 means 30 percent slower. Timeline or required loop incompatibility rejects the entire plan."
       }
      }
     }
    }
   },
   "returns": "mai.agent-result/v1 {status: prepared|committed|running, committed, baseRevision, revision, snapshotId, transaction:{id,undoToken}, changes[], identity:{status,evaluatedParts,evaluatedTimes}, artifacts[], warnings[]}",
   "sideEffects": "dry-run: draft snapshot + preview files. commit: one document transaction (scene + decisions + receipt in the journal).",
   "reversible": "undoToken",
   "preview": "returned",
   "identityImpact": "guarded",
   "examples": [
    {
     "args": {
      "plan": {
       "protocol": "mai.agent-plan/v1",
       "requestId": "direction-candy-001",
       "sessionId": "session-example",
       "documentId": "document-candy-example",
       "expectedRevision": 24,
       "mode": "dry-run",
       "label": "Variante A, ojos C, boca actual y humo más lento",
       "constraints": {
        "preserve": [
         {
          "part": {
           "partId": "mouth",
           "within": "candy"
          },
          "reference": {
           "kind": "snapshot",
           "id": "snapshot-example-24"
          },
          "channels": [
           "geometry",
           "paint",
           "expression"
          ],
          "allowRigidMotion": true
         }
        ]
       },
       "commands": [
        {
         "id": "expression",
         "type": "variant.apply",
         "target": {
          "partId": "candy"
         },
         "board": {
          "id": "sad-options",
          "version": 1
         },
         "base": "A",
         "take": {
          "eyes": "C"
         }
        },
        {
         "id": "smoke-speed",
         "type": "animation.adjust",
         "target": {
          "partId": "smoke",
          "within": "candy"
         },
         "sourceId": "smoke-flow",
         "property": "speed",
         "scale": 0.7,
         "onOverflow": "reject"
        }
       ],
       "validation": {
        "times": [
         0,
         0.66,
         1.6,
         2.8,
         4.1,
         5.2,
         6.5
        ],
        "required": [
         "structural",
         "identity"
        ],
        "preview": true
       },
       "provenance": {
        "kind": "user-direction",
        "text": "Me gusta la primera pero con los ojos de la tercera. Conserva la boca y baja 30% la velocidad del humo."
       }
      }
     },
     "why": "Illustrative IDs: read sessionId/documentId/snapshotId/board version/sourceId from scene.inspect and choices.inspect first."
    }
   ],
   "availability": {
    "status": "stable"
   },
   "destructive": false,
   "outputSchema": {
    "type": "object",
    "required": [
     "ok"
    ],
    "properties": {
     "ok": {
      "type": "boolean"
     },
     "protocol": {
      "type": "string",
      "const": "mai.agent-result/v1"
     },
     "requestId": {
      "type": "string"
     },
     "status": {
      "type": "string",
      "enum": [
       "prepared",
       "committed",
       "running",
       "unknown",
       "cancelling"
      ]
     },
     "committed": {
      "type": "boolean"
     },
     "baseRevision": {
      "type": "integer"
     },
     "revision": {
      "type": "integer"
     },
     "snapshotId": {
      "type": "string"
     },
     "transaction": {
      "type": "object",
      "properties": {
       "id": {
        "type": "string"
       },
       "undoToken": {
        "type": "string"
       }
      }
     },
     "changes": {
      "type": "array"
     },
     "identity": {
      "type": "object"
     },
     "artifacts": {
      "type": "array"
     },
     "warnings": {
      "type": "array"
     },
     "error": {
      "type": "object"
     }
    }
   }
  }
 ],
 "conventions": {
  "workflow": [
   "inspect (scene.inspect / choices.inspect / scene.identity)",
   "plan in your head: map human words → tools; ask only if a part is truly ambiguous",
   "dryRun:true for risky or identity-touching changes",
   "apply with expectedRevision",
   "preview.render and look at the PNGs",
   "identity.check / compare.frames / critique / audit",
   "explain to the human what changed and show previews",
   "iterate on feedback; undo with undoToken if wrong"
  ],
  "envelope": "Every response: {ok, tool, revision, …}. Mutations add {operation, target, changes, identityImpact, undoToken, transaction}. Errors: {ok:false, error:{code,message,candidates?,suggestions?,hint?}}.",
  "errors": {
   "REVISION_CONFLICT": "Someone edited meanwhile: re-inspect and re-plan.",
   "AMBIGUOUS_TARGET": "Several parts match: show candidates or pick by context; never guess silently.",
   "NOT_FOUND": "No such part: use suggestions or part.candidates.",
   "IDENTITY_BLOCKED": "The change violates a protected part: change approach or ask before identity.release.",
   "INVALID_ARGUMENT": "Fix arguments per schema.",
   "NOT_COMBINABLE": "Board options lack specs: build a new board with explicit ops.",
   "STALE_CHOICE": "Board was rendered for an older revision: regenerate.",
   "UNDO_NOT_LATEST": "Your token is not the latest transaction; inspect history."
  },
  "identityImpact": {
   "none": "No protected or expressive part touched.",
   "rigid": "Only rigid moves of protected parts.",
   "expression": "Expressive parts deform within the preservation budget.",
   "changed": "Protected/expressive geometry or style changed (should be rare and intentional)."
  },
  "language": "MAI never interprets natural language. You (the agent) map the human's words to these tools using inspect results, previews and history."
 },
 "vocabulary": {
  "expressionTemplates": {
   "mouth": {
    "landmarks": [
     "left",
     "right",
     "center",
     "lower"
    ],
    "params": [
     "happiness",
     "sadness",
     "anger",
     "fear",
     "surprise",
     "tiredness",
     "mouth-open",
     "mouth-wide",
     "mouth-round",
     "lips-closed",
     "smirk"
    ]
   },
   "eye": {
    "landmarks": [
     "inner",
     "outer",
     "upper",
     "lower",
     "iris"
    ],
    "params": [
     "sadness",
     "happiness",
     "anger",
     "fear",
     "surprise",
     "tiredness",
     "squint",
     "look-x",
     "look-y"
    ]
   },
   "brow": {
    "landmarks": [
     "inner",
     "middle",
     "outer"
    ],
    "params": [
     "sadness",
     "anger",
     "surprise",
     "happiness",
     "fear",
     "tiredness"
    ]
   },
   "ear": {
    "landmarks": [
     "base",
     "tip"
    ],
    "params": [
     "sadness",
     "ear-droop",
     "anger",
     "surprise",
     "fear"
    ]
   }
  },
  "preservation": {
   "strict": {
    "maxDisplacement": 0.12,
    "meaning": "Matices: la expresión apenas cambia el dibujo. Color, topología y silueta intactos; landmarks ≤12% del tamaño del rasgo."
   },
   "balanced": {
    "maxDisplacement": 0.32,
    "meaning": "Expresión legible (una sonrisa puede volverse tristeza) usando la misma boca/ojos: sin recolorear ni cambiar topología; landmarks ≤32%."
   },
   "free": {
    "maxDisplacement": 0.6,
    "meaning": "Actuación exagerada con la misma geometría: deformaciones amplias, aún sin recolorear ni sustituir partes; landmarks ≤60%."
   }
  },
  "protectionLevels": {
   "locked": "Nada puede cambiar, ni siquiera la pose.",
   "protected": "Solo movimiento rígido (posición/rotación).",
   "deformable": "Puede deformarse por expresiones/warps; sin recolorear, borrar ni cambiar topología.",
   "style-preserved": "Geometría libre; colores, gradientes y trazos intactos.",
   "topology-preserved": "Puntos móviles y estilo editable; sin añadir/quitar nodos ni dividir.",
   "color-preserved": "Cualquier cambio salvo color/gradiente/trazo.",
   "silhouette-preserved": "Deformaciones permitidas si la silueta se mantiene: identity.check mide IoU de la máscara renderizada contra una referencia (≥ 0.9).",
   "free": "Sin restricciones de identidad."
  },
  "fluidPresets": {
   "smoke": "Asciende y se enrosca; casi inmóvil en el emisor, más libre arriba.",
   "steam": "Vapor rápido y fino.",
   "fog": "Deriva lenta y amplia, sin emisor.",
   "cloud": "Ondulación muy lenta del contorno.",
   "water": "Ondas que viajan conservando la forma.",
   "wave": "Ola marcada y regular.",
   "river": "Corriente rápida con remolinos pequeños.",
   "rain": "Vibración descendente.",
   "wind": "Ráfagas que empujan lejos del anclaje.",
   "fire": "Lenguas rápidas con parpadeo; base anclada.",
   "lava": "Viscosa: grande, lenta y densa.",
   "magic": "Espiral alrededor del emisor.",
   "electricity": "Temblor de alta frecuencia por pasos.",
   "dust": "Deriva con remolinos suaves.",
   "snow": "Caída lenta con vaivén.",
   "cloth": "Ondas grandes desde el borde sujeto.",
   "hair": "Mechones que se mueven más en las puntas.",
   "grass": "Balanceo desde la raíz."
  },
  "springPresets": {
   "tail": "Cola: sigue el salto con retraso suave y rebote leve.",
   "ears": "Orejas: reacción rápida, poco rebote.",
   "hair": "Pelo: inercia y vaivén.",
   "cloth": "Ropa: pesada y lenta.",
   "antenna": "Antenas: elásticas con overshoot.",
   "accessory": "Accesorio colgante.",
   "plant": "Planta: balanceo amortiguado."
  },
  "deliveryProfiles": {
   "editable": {
    "when": "Seguir editando en MAI; conserva rig, expresiones y modificadores.",
    "maxPaths": 100000,
    "maxBytes": 33554432,
    "technologies": [
     "mai-metadata",
     "smil",
     "filters",
     "masks"
    ]
   },
   "archive": {
    "when": "Conservar el máster aprobado sin pérdidas.",
    "maxPaths": 100000,
    "maxBytes": 33554432,
    "technologies": [
     "mai-metadata",
     "smil",
     "filters",
     "masks"
    ]
   },
   "high-quality": {
    "when": "Póster, render final o hero: fidelidad sobre peso.",
    "maxPaths": 60000,
    "maxBytes": 16777216,
    "technologies": [
     "smil",
