     "masks"
    ]
   },
   "web": {
    "when": "Página web con animación SMIL; Chromium/Firefox/WebKit.",
    "maxPaths": 20000,
    "maxBytes": 4194304,
    "technologies": [
     "smil",
     "css",
     "filters",
     "masks"
    ]
   },
   "web-light": {
    "when": "Ilustración secundaria o móvil lento; acepta pérdida de microdetalle.",
    "maxPaths": 4000,
    "maxBytes": 1048576,
    "technologies": [
