    ]
   }
  },
  "easings": [
   "linear",
   "ease-in-out",
   "ease-in",
   "ease-out",
   "overshoot",
   "anticipate",
   "step",
   "cubic-bezier(x1,y1,x2,y2)"
  ],
  "slots": [
   "mouth",
   "eyes",
   "brows",
   "ears",
   "face"
  ]
 }
}

{
 "ok": true,
 "tool": "choices.inspect",
 "revision": 16,
 "choice": {
  "id": "expr-sadness-muucdgrd",
  "version": 1,
  "kind": "expression",
  "status": "chosen",
  "revision": 15,
  "prompt": "¿Cómo quieres que se vea la tristeza de Candy?",
  "recommended": "A",
  "reason": "Concentra la emoción en los ojos y deforma menos la boca: máxima legibilidad con mínima deformación.",
  "time": 1,
  "selected": "D-A-eyesC-keep",
  "combinableSlots": [
   "mouth",
   "eyes"
  ],
  "options": [
   {
    "id": "A",
    "position": 1,
    "label": "Contenida",
    "description": "La emoción vive en los ojos; la boca apenas cambia.",
    "combinable": true,
    "params": {
     "sadness@mouth": 0.383,
     "sadness@eyes": 0.807
    },
    "slots": {
     "mouth": {
      "sadness": 0.383
     },
     "eyes": {
