     }
    },
    "previewPath": "/var/folders/tr/c7sds6b95pl373kj_mhpd7sc0000gn/T/mai-s4-candy-r3/.cache/choices/expr-sadness-muucdgrd-A.png",
    "operations": 1
   },
   {
